const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const assert = require('node:assert/strict');

const root = 'public-artifacts/pylibczirw';
const data = 'pylibCZIrw/tests/integration/test_data';
const manifestPath = path.join(root, data, 'fixture_manifest.json');
const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
const read = name => JSON.parse(fs.readFileSync(path.join(__dirname, name), 'utf8'));
const hash = bytes => crypto.createHash('sha256').update(bytes).digest('hex').toUpperCase();
const id = 'legacy-reference-review-20261015';
const destination = `${data}/fixture_public_legacy_review.json`;
assert(!fs.existsSync(path.join(root,destination)));
assert(!manifest.reference_audits.some(record => record.id === id));
for(const pin of manifest.reference_audits){const bytes=fs.readFileSync(path.join(root,pin.path));assert.equal(bytes.length,pin.size_bytes);assert.equal(hash(bytes),pin.sha256);}
const results = read('reference-checks-v2.json');
assert.equal(results.cases.length, 9);
assert(results.cases.every(record => record.state === 'reference-verified'));
const sources = ['review_references.py','record_review.js'].map(name => {
  const bytes = fs.readFileSync(path.join(__dirname,name));
  return {name,size_bytes:bytes.length,sha256:hash(bytes),source_utf8:bytes.toString('utf8')};
});
const report = {
  schema_version:1,id,recorded_on:'2026-10-15',
  state:'partial-request-scoped-reference-evidence; owner scope decision pending',
  record:'doc/fixture_policy.md',
  command:['python','-I',path.join(__dirname,'review_references.py')],
  reader_commit:'ab0f6388c39388a4e38d37810cdd693d41fa5c95',
  independent_results:results,
  initial_byte_comparison:read('reference-checks.json'),
  sources,
  verification_scope:{writer_pixels:'Three exact uncompressed native-order input/reference pairs used by integration/write/test_write.py: BGR24, BGR48 and Gray8; no wrapper/libCZI imports.',metadata_content:'Six exact ordered XML element/attribute/significant-text content comparisons; whitespace-only indentation/declaration spelling ignored. This does not independently verify exact native XML serialization.',historical_recipes:'Unknown remains unknown. Verification of current reference values is not proof of who originally generated them or with which reader/version.'},
  source_review:{repository:manifest.repository_snapshot.repository,introduction_evidence:manifest.asset_defaults.origin.evidence,licensing:manifest.asset_defaults.rights,privacy_decision:'existing-fixture-reuse-20261015',producer_clues:'Collection-level ZEN/CZICmd/pylibCZIrw report and embedded application clues remain qualified, not per-file provenance.',known_new_restrictions_identified:false,limits:'No newly identified exception is not proof that none exists. No license or historical producer/recipe is inferred from byte equality or a passing regression.'},
  proposed_owner_decision:{state:'pending',scope:'T01 corpus/evidence completion only',recommendation:'Accept explicitly unknown original producer/reference-generation details for the existing approved corpus where unavailable. Use independently verified values and literal fixtures as required oracles; retain remaining legacy zoom/conversion/format snapshots as regression-only evidence, not new-feature correctness oracles.',does_not_authorize:['relicensing or removing existing tests/references','known third-party restrictions','new API or release-gate passes','M0-12 sign-off','silently treating unverified historical expectations as independent oracles']},
  limits:'No fixture/reference bytes changed, historical records overwritten, source history fabricated, blanket reference promotion, new-API certification or T01 completion.'
};
const bytes = Buffer.from(JSON.stringify(report,null,2)+'\n');
fs.writeFileSync(path.join(root,destination),bytes);
manifest.reference_audits.push({id,recorded_on:'2026-10-15',path:destination,size_bytes:bytes.length,sha256:hash(bytes),state:'partial-reference-evidence',record:report.record,scope:'Three required writer pixel references verified exactly; six global XML references verified for content only.',limits:'Current values only; original producers/recipes, native XML formatting and remaining legacy zoom/conversion expectations are not proven. Owner corpus/evidence scope decision remains pending.'});
manifest.provenance_scope_decision = {...report.proposed_owner_decision,evidence:id};
for(const entry of manifest.existing_test_references){
  const matches=results.cases.filter(record=>entry.pairs?.some(pair=>{
    if(Array.isArray(pair)) return pair[0]===record.input_asset_id && (pair[1]===record.reference_asset_id || (Array.isArray(pair[1])&&pair[1].includes(record.reference_asset_id)));
    return JSON.stringify(pair).includes(record.input_asset_id)&&JSON.stringify(pair).includes(record.reference_asset_id);
  }));
  if(matches.length) entry.scoped_reference_reviews=[...(entry.scoped_reference_reviews||[]),{run:id,cases:matches.map(record=>record.id),limits:'Only named current input/reference requests are verified; XML content is not exact native serialization.'}];
}
const group = manifest.required_case_groups.find(group=>group.id==='C07');
group.reference_runs.push(id);
group.remaining_reference_scope='Three writer pixel references are independently exact and six global XML contents match. Historical generation and exact native XML formatting are not proven; owner acceptance of declared unknown history and regression-only legacy snapshots is pending.';
const rights=manifest.blockers.find(record=>record.id==='B-RIGHTS');
rights.needed='Record owner acceptance or rejection of explicitly unknown producer/recipe history under the where-known policy. Existing repository licensing/reuse evidence is unchanged; do not infer a new per-file licensing requirement merely from unknown acquisition history.';
const oracles=manifest.blockers.find(record=>record.id==='B-ORACLES');
oracles.scope='Remaining historical zoom/conversion/exact-serialization scope and owner corpus-evidence decision; required writer pixels and six global XML contents now have independent evidence.';
oracles.needed='Owner decides whether remaining historical snapshots stay regression-only rather than required independent new-feature oracles. If rejected, independently verify the specifically required remaining requests; do not regenerate or overwrite snapshots.';
fs.writeFileSync(manifestPath,JSON.stringify(manifest,null,4)+'\n');
console.log(JSON.stringify({record:destination,size_bytes:bytes.length,sha256:hash(bytes),exact_pixel_pairs:3,semantic_XML_pairs:6,decision:'pending'},null,2));
